INSERT INTO `paymentmethods` (`methodId`, `methodName`, `methodLogo`, `methodVisibleName`, `methodCallback`, `methodMin`, `methodMax`, `methodFee`, `methodBonusPercentage`, `methodBonusStartAmount`, `methodCurrency`, `methodStatus`, `methodExtras`, `methodPosition`, `methodInstructions`) VALUES
(100, '🇵🇭 Philippines Payment Methods', 'img/payments/manual.svg', '🇵🇭 Philippines Payment Methods', '', 1, 1, 0, 0, 0, '', '0', '', 2, '<div class=\"panel-body border-solid border-rounded text-center\" bis_skin_checked=\"1\"><!-- 🇵🇭 SMMGEN Payment Methods (Scoped, Responsive, #6336f1 Theme) -->\n<!-- QnJhbmRzb2ZwYW5lbC5jb20gUEhQIFRlbXBsYXRl -->\n<div id=\"smmgen-pay\" bis_skin_checked=\"1\">\n  <div class=\"sp-card\" bis_skin_checked=\"1\">\n    <!-- Header -->\n    <div class=\"sp-hdr\" bis_skin_checked=\"1\">\n      <div class=\"sp-title\" bis_skin_checked=\"1\">🇵🇭 Philippines Payment Methods</div>\n      <div class=\"sp-rate-badge\" bis_skin_checked=\"1\">\n        💱 <span class=\"sp-rate-num\">1 USD = <strong>60</strong> PHP</span>\n      </div>\n    </div>\n\n    <div class=\"sp-body\" bis_skin_checked=\"1\">\n      <div class=\"sp-grid\" bis_skin_checked=\"1\">\n\n        <!-- GCash -->\n        <section class=\"sp-sec\">\n          <div class=\"sp-sec-head\" bis_skin_checked=\"1\">\n            <img class=\"sp-icon\" src=\"https://brandlogos.net/wp-content/uploads/2024/01/gcash-logo_brandlogos.net_kiaqh-512x427.png\" alt=\"GCash Icon\">\n            <h3 class=\"sp-sec-title m0\">GCash</h3>\n          </div>\n\n          <div class=\"sp-box sp-equal\" bis_skin_checked=\"1\">\n            <div class=\"sp-stack\" bis_skin_checked=\"1\">\n              <img class=\"sp-logo\" src=\"https://prd-mktg-konghq-com.imgix.net/images/2023/11/6553cc4c-gcash-logo-svg.png?auto=format&amp;fit=max&amp;w=2560\" alt=\"GCash Logo\">\n              <!-- requested line break text inside the card -->\n              <div class=\"sp-sub\" bis_skin_checked=\"1\"> Safe &amp; Instant Transfer<br><br><br></div>\n\n              <div class=\"sp-row sm\" bis_skin_checked=\"1\">\n                <div class=\"sp-label\" bis_skin_checked=\"1\">Account Name</div>\n                <div class=\"sp-val\" bis_skin_checked=\"1\">E*** A.</div>\n              </div>\n              <div class=\"sp-sep\" bis_skin_checked=\"1\"></div>\n              <div class=\"sp-row sm\" id=\"sp-gcash-box\" bis_skin_checked=\"1\">\n                <div class=\"sp-label\" bis_skin_checked=\"1\">Number</div>\n                <div class=\"sp-val sp-number\" id=\"sp-gcash-number\" bis_skin_checked=\"1\">09953149939</div>\n              </div>\n            </div>\n            <!-- GCash button: Copy Number (as requested) -->\n            <button type=\"button\" class=\"sp-btn full\" onclick=\"spCopy(\'#sp-gcash-number\')\">Copy Number</button>\n          </div>\n        </section>\n\n        <!-- Maya / Bank -->\n        <section class=\"sp-sec\">\n          <div class=\"sp-sec-head\" bis_skin_checked=\"1\">\n            <img class=\"sp-icon\" src=\"https://images.crunchbase.com/image/upload/c_pad,f_auto,q_auto:eco,dpr_1/amx0mdduyvb5lzhn5mtr\" alt=\"Maya Icon\">\n            <h3 class=\"sp-sec-title m0\">Maya / Bank</h3>\n          </div>\n\n          <div class=\"sp-box sp-equal sp-center\" bis_skin_checked=\"1\">\n            <!-- Maya brand logo inside card -->\n            <img class=\"sp-logo\" src=\"https://support.mayabank.ph/s/sfsites/c/resource/1725556845000/MayabankLogoNew?\" alt=\"Maya Logo\">\n            <div class=\"sp-box-title\" bis_skin_checked=\"1\">Scan &amp; Pay</div>\n            <img class=\"sp-qr-img\" id=\"sp-maya-qr\" src=\"/\" alt=\"Maya/Bank QR\" loading=\"lazy\">\n            <div class=\"sp-hint\" bis_skin_checked=\"1\">Scan using <b>Maya</b> or your PH banking app.</div>\n            <!-- Maya button: DIRECT download QR (force download) -->\n            <a class=\"sp-btn full\" href=\"#\" onclick=\"spDownloadQR(\',\'smmgen-maya-qr.jpg\'); return false;\">\n              Download QR\n            </a>\n          </div>\n        </section>\n\n      </div>\n\n      <!-- Contact Telegram -->\n      <div class=\"sp-contact\" bis_skin_checked=\"1\">\n        <a class=\"sp-contact-btn\" href=\"https://t.me/AcucGeraldBOOSTING\" target=\"_blank\" rel=\"noopener\">\n          <img class=\"sp-tg-icon\" src=\"https://upload.wikimedia.org/wikipedia/commons/thumb/8/82/Telegram_logo.svg/1200px-Telegram_logo.svg.png\" alt=\"Telegram\">\n          Contact Telegram\n        </a>\n        <p class=\"sp-note-below\">After sending money, please confirm with details via Telegram.</p>\n      </div>\n    </div>\n\n    <div id=\"sp-toast\" class=\"sp-toast\" bis_skin_checked=\"1\">✅ Number copied!</div>\n  </div>\n</div>\n\n<style>\n  #smmgen-pay{\n    --accent:#6336f1; --accent-600:#5227ea; --text:#111827; --muted:#6b7280; --card:#fff; --border:#f1f5f9;\n    --box-bg:#f7f4ff; --box-br:#e6ddff; --sep:#e6ddff; --qr-br:#e6ddff;\n    --xA:\"GEN-Engine|smmgen.com PHP Template\"; --xB:\"smmgen.com|v1\";\n    max-width:960px;margin:24px auto;font-family:system-ui,-apple-system,Segoe UI,Roboto,Arial,sans-serif;\n  }\n\n  .sp-card{border-radius:16px;background:var(--card);border:1px solid var(--border);box-shadow:0 8px 24px rgba(0,0,0,.06);position:relative;overflow:hidden}\n\n  /* Header – full purple gradient */\n  .sp-hdr{padding:18px 20px;text-align:center;background:linear-gradient(90deg,#6336f1 0%,#875cf7 100%);color:#fff}\n  .sp-title{font-weight:800;font-size:18px}\n  .sp-rate-badge{display:inline-flex;align-items:center;gap:8px;margin-top:8px;background:#fff;color:#4b2bbd;border:2px solid #e5ddff;padding:8px 12px;border-radius:999px;box-shadow:0 6px 18px rgba(99,54,241,.12);font-weight:800;font-size:14px}\n  .sp-rate-num strong{color:#6336f1}\n\n  /* Layout */\n  .sp-body{padding:18px}\n  .sp-grid{display:grid;grid-template-columns:1fr;gap:18px}\n  @media(min-width:900px){.sp-grid{grid-template-columns:1fr 1fr}}\n\n  /* Section headings */\n  .sp-sec-title{font-size:16px;font-weight:800;color:var(--accent);margin:0 0 8px}\n  .sp-sec-title.m0{margin:0}\n  .sp-sec-head{display:flex;align-items:center;gap:8px;margin-bottom:8px}\n  .sp-icon{height:20px;width:auto;display:block}\n\n  /* Boxes */\n  .sp-box{\n    background:var(--box-bg);border:1px solid var(--box-br);border-radius:14px;padding:14px;\n    display:flex;flex-direction:column;justify-content:space-between;box-shadow:0 6px 16px rgba(99,54,241,.08)\n  }\n  /* Equal height enforcement */\n  .sp-equal{min-height: 380px;} /* keeps both cards visually equal with button rows */\n  .sp-center{display:flex;flex-direction:column;align-items:center;justify-content:center;gap:10px;text-align:center}\n  .sp-stack{display:flex;flex-direction:column;gap:10px;align-items:center;text-align:center}\n  .sp-logo{width:120px;max-width:70%;height:auto;margin:0 auto 4px;display:block}\n  .sp-sub{font-size:12px; line-height:1.1; color:#7c5af3; margin-bottom:6px;} /* GCash small line under logo */\n\n  .sp-row{display:flex;justify-content:space-between;width:100%;max-width:280px}\n  .sp-label{font-weight:700;color:#7c5af3}\n  .sp-val{font-weight:800;color:var(--text);word-break:break-all}\n  .sp-number{font-family:ui-monospace,Menlo,Consolas,monospace;font-size:15px;letter-spacing:.4px}\n  .sp-sep{height:1px;background:var(--sep);width:100%;max-width:280px}\n\n  /* Minimal QR (brandsofpanel style) */\n  .sp-box-title{font-weight:800;color:#7c5af3}\n  .sp-qr-img{\n    width:50%;max-width:240px;min-width:130px;height:auto;border-radius:12px;\n    border:1px solid var(--qr-br);background:#fff;box-shadow:0 8px 18px rgba(99,54,241,.10);margin:10px auto;\n  }\n  .sp-hint{font-size:12px;color:#6b7280}\n\n  /* Buttons */\n  .sp-btn{border:none;border-radius:10px;padding:10px 16px;font-weight:800;background:var(--accent);color:#fff;cursor:pointer;transition:transform .06s ease,filter .2s;margin-top:10px;text-align:center;display:inline-block}\n  .sp-btn.full{width:100%;max-width:280px;align-self:center}\n  .sp-btn:hover{filter:brightness(0.95)}\n  .sp-btn:active{transform:translateY(1px)}\n\n  /* Contact Telegram */\n  .sp-contact{text-align:center;margin-top:22px}\n  .sp-contact-btn{display:inline-flex;align-items:center;gap:8px;padding:10px 22px;border-radius:10px;background:var(--accent);color:#fff;text-decoration:none;font-weight:800;font-size:15px;transition:background .2s,transform .06s ease}\n  .sp-contact-btn:hover{background:var(--accent-600)}\n  .sp-contact-btn:active{transform:translateY(1px)}\n  .sp-tg-icon{height:17px;width:auto;display:block}\n  .sp-note-below{font-size:12px;text-align:center;color:#6b7280;margin-top:8px;font-weight:700}\n\n  /* Toast */\n  .sp-toast{position:absolute;left:50%;transform:translateX(-50%) translateY(10px);bottom:12px;background:var(--accent);color:#fff;padding:8px 12px;border-radius:10px;font-weight:700;opacity:0;pointer-events:none;transition:opacity .25s,transform .25s;box-shadow:0 10px 20px rgba(0,0,0,.15)}\n  .sp-toast.show{opacity:1;transform:translateX(-50%) translateY(0)}\n</style>\n\n<script>\n  (function(){ const _ref=\"QnJhbmRzb2ZwYW5lbC5jb20gUEhQIFRlbXBsYXRl\"; void _ref; })();\n\n  function spCopy(sel){\n    const root=document.getElementById(\'smmgen-pay\');\n    const el=root?root.querySelector(sel):null;\n    const txt=el?(el.innerText||el.textContent).trim():\"\";\n    if(!txt)return;\n    if(navigator.clipboard&&window.isSecureContext){\n      navigator.clipboard.writeText(txt).then(()=>spToast(\'✅ Number copied!\'));\n    }else{\n      const ta=document.createElement(\'textarea\');ta.value=txt;\n      document.body.appendChild(ta);ta.select();\n      try{document.execCommand(\'copy\');spToast(\'✅ Number copied!\');}\n      catch(e){spToast(\'❌ Copy not supported\');}\n      finally{document.body.removeChild(ta);}\n    }\n    const box=el?el.closest(\'.sp-row\'):null;\n    if(box){const orig=box.style.background;box.style.background=\'#efe9ff\';setTimeout(()=>box.style.background=orig||\'\',600);}\n  }\n\n  // Force file download for external QR (works on most browsers, with fallback)\n  async function spDownloadQR(url, filename){\n    try{\n      const res = await fetch(url, {mode:\'cors\'});\n      const blob = await res.blob();\n      const objectUrl = URL.createObjectURL(blob);\n      const a = document.createElement(\'a\');\n      a.href = objectUrl;\n      a.download = filename || \'qr.jpg\';\n      document.body.appendChild(a);\n      a.click();\n      a.remove();\n      setTimeout(()=>URL.revokeObjectURL(objectUrl), 1500);\n      spToast(\'✅ QR download started\');\n    }catch(e){\n      // Fallback: navigate to the file (browser may still offer save)\n      const a = document.createElement(\'a\');\n      a.href = url;\n      a.target = \'_blank\';\n      document.body.appendChild(a);\n      a.click();\n      a.remove();\n    }\n  }\n\n  function spToast(msg){\n    const t=document.getElementById(\'sp-toast\');\n    if(!t)return;\n    t.textContent=msg;t.classList.add(\'show\');\n    setTimeout(()=>t.classList.remove(\'show\'),2000);\n  }\n</script>\n</div>'),
